Roleplay_Brookhaven.codigoLuau:
--!strict
export type Profile = {coins:number, level:number, checkpoint:number, inventory:{[string]:number}, buttons:{[string]:boolean}}
return {}

--!strict
local Http=game:GetService("HttpService")
local ServerStorage=game:GetService("ServerStorage")
local M={}
local queue:{any}={}
local settings=ServerStorage:FindFirstChild("WayneTelemetry")
local config:any=if settings and settings:IsA("ModuleScript") then require(settings) else nil
function M.Log(player:Player,reason:string)
 local entry={id=Http:GenerateGUID(false),userId=tostring(player.UserId),motivo=string.sub(reason,1,300),data=os.date("!%Y-%m-%dT%H:%M:%SZ")}
 warn("WAYNE_ANTI_HACK",entry.userId,entry.motivo)
 if #queue<100 then table.insert(queue,entry) end
end
function M.Start()
 task.spawn(function()
  while task.wait(10) do
   if not config or type(config.url)~="string" or not string.match(config.url,"^https://") or not config.token then continue end
   if #queue==0 then continue end
   local batch=table.clone(queue)
   local ok,res=pcall(function()
    return Http:RequestAsync({Url=config.url,Method="POST",Headers={["Content-Type"]="application/json",Authorization="Bearer "..config.token},Body=Http:JSONEncode({gameId=config.gameId,logs=batch})})
   end)
   if ok and res.Success then for _=1,#batch do table.remove(queue,1) end end
  end
 end)
end
return M

